# ── UPDATE JSON ───────────────────────────────────────────────────────────────
print("Loading JSON…")
with open(ROOT / 'data' / 'two-layers.json', encoding='utf-8') as f:
    data = json.load(f)

for ch in data['chapters']:
    ch_id = ch['id']
    if ch_id in CH_2026:
        ch['simulation']['paragraphs']['en'] = CH_2026[ch_id]
    if ch_id in CH_3026:
        ch['archive']['paragraphs']['en'] = CH_3026[ch_id]

with open(ROOT / 'data' / 'two-layers.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

print(f"JSON written. {len(data['chapters'])} chapters updated.")


